// Event type chip selector (desktop)
document.querySelectorAll('.event-type-chip').forEach(chip => {
  chip.addEventListener('click', () => {
    document.querySelectorAll('.event-type-chip').forEach(c => c.classList.remove('active'));
    chip.classList.add('active');
    document.getElementById('eventType').value = chip.dataset.value;
    document.getElementById('eventTypeSelect').value = chip.dataset.value;
  });
});

// Event type dropdown (mobile)
document.getElementById('eventTypeSelect').addEventListener('change', function() {
  document.getElementById('eventType').value = this.value;
  document.querySelectorAll('.event-type-chip').forEach(c => {
    c.classList.toggle('active', c.dataset.value === this.value);
  });
});

// Form submit
document.getElementById('contactForm').addEventListener('submit', function(e) {
  e.preventDefault();
  const firstName = document.getElementById('firstName').value.trim();
  const lastName  = document.getElementById('lastName').value.trim();
  const phone     = document.getElementById('phone').value.trim();
  const email     = document.getElementById('email').value.trim();
  const eventType = document.getElementById('eventType').value;
  const message   = document.getElementById('message').value.trim();
  const offersOptIn = document.getElementById('offersOptIn').checked;
  const text = `Hi Utsah Events! 👋\n\nName: ${firstName} ${lastName}\nPhone: ${phone}${email ? `\nEmail: ${email}` : ''}\nEvent: ${eventType}\n\nMessage: ${message}${offersOptIn ? '\n\n(Would like to receive exclusive offers and updates)' : ''}`;
  const waUrl    = `https://api.whatsapp.com/send/?phone=918200395197&text=${encodeURIComponent(text)}`;
  const emailUrl = `mailto:sales@utsahevents.com?subject=Event Enquiry — ${eventType}&body=${encodeURIComponent(text)}`;
  document.getElementById('sendChoiceModal').style.display = 'flex';
  document.getElementById('sendViaWA').onclick = () => { window.open(waUrl, '_blank'); closeModal(); };
  document.getElementById('sendViaEmail').onclick = () => { window.open(emailUrl); closeModal(); };
  function closeModal() {
    document.getElementById('sendChoiceModal').style.display = 'none';
    document.getElementById('contactForm').style.display = 'none';
    document.getElementById('formSuccess').style.display = 'block';
  }
  document.getElementById('modalClose').onclick = () => {
    document.getElementById('sendChoiceModal').style.display = 'none';
  };
});

// Menu controls
(function() {
  const dropBtn = document.getElementById('dropdownBtn');
  const dropMenu = document.getElementById('dropdownMenu');
  const closeBtn = document.getElementById('menuCloseBtn');
  const backdrop = document.getElementById('navBackdrop');
  function open() { if (!dropMenu) return; dropMenu.classList.add('open'); if (dropBtn) { dropBtn.classList.add('active'); dropBtn.setAttribute('aria-expanded','true'); } }
  function close() { if (!dropMenu) return; dropMenu.classList.remove('open'); if (dropBtn) { dropBtn.classList.remove('active'); dropBtn.setAttribute('aria-expanded','false'); } }
  if (dropBtn) dropBtn.addEventListener('click', e => { e.stopPropagation(); dropMenu.classList.contains('open') ? close() : open(); });
  if (closeBtn) closeBtn.addEventListener('click', close);
  if (backdrop) backdrop.addEventListener('click', close);
  if (dropMenu) dropMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', close));
  window.addEventListener('scroll', () => { if (window.scrollY > 20) close(); }, { passive: true });
})();

// Hero scroll cue — hide once the page scrolls, reappear back at the hero
(function() {
  const cue = document.querySelector('.contact-hero__scroll');
  if (!cue) return;
  const onScroll = () => {
    cue.style.opacity = window.scrollY > 40 ? '0' : '';
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();
